import{_ as t,o,c,a5 as d}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"MyBatis 框架概述","description":"","frontmatter":{"title":"MyBatis 框架概述","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/MyBatis 框架概述.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/MyBatis 框架概述.md"}'),a={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/MyBatis 框架概述.md"};function s(r,e,n,p,i,l){return o(),c("div",null,[...e[0]||(e[0]=[d("<div><p><code>mybatis</code> 是一个优秀的基于 <code>java</code> 的持久层框架，它内部封装了 <code>jdbc</code>，使开发者只需要关注 <code>sql</code> 语句本身，而不需要花费精力去处理加载驱动、创建连接、创建 <code>statement</code> 等繁杂的过程。</p><p><code>mybatis</code></p><p>通过 <code>xml</code> 或注解的方式将要执行的各种 <code>statement</code> 配置起来，并通过 <code>java</code> 对象和 <code>statement</code> 中<code>sql</code> 的动态参数进行映射生成最终执行的 <code>sql</code> 语句，最后由 <code>mybatis</code> 框架执行 <code>sql</code> 并将结果映射为 <code>java</code> 对象并返回。 采用 <code>ORM</code> 思想解决了实体和数据库映射的问题，对 <code>jdbc</code> 进行了封装，屏蔽了 <code>jdbc api</code> 底层访问细节，使我们不用与 <code>jdbc api</code> 打交道，就可以完成对数据库的持久化操作。 为了我们能够更好掌握框架运行的内部过程，并且有更好的体验，下面我们将从自定义 <code>Mybatis</code> 框架开始来学习框架。此时我们将会体验框架从无到有的过程体验，也能够很好的综合前面阶段所学的基础。</p><p><code>JDBC</code> <strong>编程的分析</strong></p><p><code>jdbc</code></p><p><strong>程序的回顾</strong></p><p>public static void main(String[] args) { Connection connection = null; PreparedStatement preparedStatement = null; ResultSet resultSet = null; try { // 加载数据库驱动</p><p>Class.forName(&quot;com.mysql.jdbc.Driver&quot;); // 通过驱动管理类获取数据库链接</p><p>connection = DriverManager .getConnection(&quot;jdbc:mysql://localhost:3306/mybatis?characterEncoding=utf-8&quot;,&quot;ro ot&quot;, &quot;root&quot;); // 定义 <code>sql</code> 语句 <code>?</code>表示占位符</p><p>String sql = &quot;select * from user where username = ?&quot;; ￼<code>//</code>获取预处理</p><p>statement preparedStatement = connection.prepareStatement(sql); // 设置参数，第一个参数为 <code>sql</code> 语句中参数的序号（从 <code>1</code> 开始），第二个参数为设置的 参数值</p><p><code>preparedStatement.setString(1, &quot;</code></p><p>王五</p><p>&quot;); // 向数据库发出 <code>sql</code> 执行查询，查询出结果集</p><p>resultSet = preparedStatement.executeQuery(); // 遍历查询结果集</p><p>while(resultSet.next()){ System.out.println(resultSet.getString(&quot;id&quot;)+&quot; &quot;+resultSet.getString(&quot;username&quot;)); } } catch (Exception e) { e.printStackTrace(); }finally{ // 释放资源</p><p>if(resultSet!=null){ try { resultSet.close(); } catch (SQLException e) { e.printStackTrace(); } } if(preparedStatement!=null){ try { preparedStatement.close(); } catch (SQLException e) { e.printStackTrace(); } } if(connection!=null){ try { connection.close(); } catch (SQLException e) { // TODO Auto-generated catch block e.printStackTrace(); } } } } 上边使用 <code>jdbc</code> 的原始方法（未经封装）实现了查询数据库表记录的操作。</p><p><code>jdbc</code> <strong>问题分析</strong><code>1</code>、数据库链接创建、释放频繁造成系统资源浪费从而影响系统性能，如果使用数据库链接池可解决此问题。</p><p><code>2</code></p><p>、<code>Sql</code> 语句在代码中硬编码，造成代码不易维护，实际应用 <code>sql</code> 变化的可能较大，<code>sql</code> 变动需要改变 <code>java</code>代码。 <code>3</code>、使用 <code>preparedStatement</code> 向占有位符号传参数存在硬编码，因为 <code>sql</code> 语句的 <code>where</code> 条件不一定，可能多也可能少，修改 <code>sql</code> 还要修改代码，系统不易维护。 <code>4</code>、对结果集解析存在硬编码（查询列名），<code>sql</code> 变化导致解析代码变化，系统不易维护，如果能将数据库记录封装成 <code>pojo</code> 对象解析比较方便。</p></div>",1)])])}const S=t(a,[["render",s]]);export{m as __pageData,S as default};
